const dealerInfo = await browserjs(tabId, () => {
  const dealerSection = document.querySelector('[data-tracking-id*="dealer"], .dealer-info, #dealer-info') || Array.from(document.querySelectorAll('div, section')).find(el => el.innerText?.includes('Dealer Info') || el.innerText?.includes('About the Dealer') || el.innerText?.includes('Dealership'));

  // Also look for seller name
  const allText = document.body.innerText;
  const match = allText.match(/(?:Dealer|Sold by|Dealership|Location|Seller)[\s\S]{1,200}?(?:Phone|Contact|Address|Map|miles away)/i);

  return {
    dealerSectionText: dealerSection?.innerText?.slice(0, 500),
    matchText: match ? match[0] : null
  };
});
console.log("Dealer info:", JSON.stringify(dealerInfo, null, 2));

// Let's also check all headings or buttons with dealer
